// =====================================================================
//  CONFIGURATION : valeurs par défaut (modifiables ici)
//  Les clés listées dans OVERRIDABLE peuvent être surchargées par le Webhook
//  (champs de formulaire, query string ou body JSON).
// =====================================================================
const CONFIG = {
  // --- Fichiers ---
  workRoot: '/home/node/.n8n-files',                      // dossier de travail (autorisé par n8n)
  manualVideoPath: '/home/node/.n8n-files/session.avi',   // vidéo utilisée par le Manual Trigger

  // --- Extraction des frames ---
  mode: 'interval',        // 'interval' = 1 frame toutes les N s | 'scene' = quand l'écran change
  frameIntervalSec: 5,     // mode interval
  sceneThreshold: 0.01,    // mode scene : 0.005 = très sensible ... 0.1 = peu sensible
  maxGapSec: 30,           // mode scene : force une frame au moins toutes les N secondes
  maxFrames: 600,          // garde-fou coût / durée
  frameWidth: 1280,        // largeur max des frames (px)
  jpegQuality: 3,          // 2 (meilleure) .. 31 (pire)

  // --- Analyse vision ---
  provider: 'anthropic',   // 'anthropic' | 'ollama' (100 % local, rien ne sort de la machine)
  batchSize: 4,            // frames envoyées par appel au modèle
  contextFramesCount: 3,   // analyses précédentes renvoyées en contexte au lot suivant
  visionModel: 'claude-sonnet-5-5',        // ex. 'claude-haiku-4-5-20251001' pour réduire le coût
  summaryModel: 'claude-sonnet-5-5',
  ollamaUrl: 'http://host.docker.internal:11434',
  ollamaVisionModel: 'qwen2.5vl:7b',
  ollamaSummaryModel: 'qwen2.5:14b',
  ollamaVisionNumCtx: 8192,
  ollamaSummaryNumCtx: 32768,

  // --- Compte rendu ---
  language: 'français',
  sessionContext: '',      // ex. "Maintenance d'un serveur Debian via RDP"
  summaryMaxChars: 120000, // taille max de la chronologie envoyée à la synthèse

  // --- Divers ---
  cleanupFrames: false     // true = supprime les JPEG une fois le rapport généré
};

const OVERRIDABLE = ['mode', 'frameIntervalSec', 'sceneThreshold', 'maxGapSec', 'maxFrames', 'batchSize',
  'contextFramesCount', 'provider', 'visionModel', 'summaryModel', 'language', 'sessionContext', 'cleanupFrames'];

const item = $input.item;
const isWebhook = !!item.json.headers;
const input = Object.assign({}, item.json.query || {}, item.json.body || {});

const cfg = Object.assign({}, CONFIG);
for (const k of OVERRIDABLE) {
  const v = input[k];
  if (v === undefined || v === null || v === '') continue;
  const t = typeof CONFIG[k];
  cfg[k] = t === 'number' ? Number(v) : t === 'boolean' ? String(v) === 'true' : String(v);
}

// --- Validation ---
if (!['interval', 'scene'].includes(cfg.mode)) throw new Error('mode invalide : ' + cfg.mode);
if (!['anthropic', 'ollama'].includes(cfg.provider)) throw new Error('provider invalide : ' + cfg.provider);
for (const k of ['frameIntervalSec', 'sceneThreshold', 'maxGapSec', 'maxFrames', 'batchSize']) {
  if (!Number.isFinite(cfg[k]) || cfg[k] <= 0) throw new Error('Paramètre numérique invalide : ' + k);
}
cfg.batchSize = Math.min(Math.floor(cfg.batchSize), 20);
cfg.maxFrames = Math.floor(cfg.maxFrames);
cfg.contextFramesCount = Math.max(0, Math.floor(Number(cfg.contextFramesCount) || 0));

// --- Identifiants du job ---
const stamp = new Date().toISOString().replace(/[-:T.Z]/g, '').slice(0, 14);
const jobId = 'job_' + stamp + '_' + Math.random().toString(36).slice(2, 6);
const jobDir = cfg.workRoot + '/' + jobId;
const framesDir = jobDir + '/frames';

// --- Source vidéo : upload (binaire) ou chemin local ---
const binKeys = Object.keys(item.binary || {});
const hasUpload = binKeys.length > 0;
let videoPath;
if (hasUpload) {
  const orig = item.binary[binKeys[0]].fileName || 'session.avi';
  const m = orig.match(/\.(avi|mp4|mkv|mov|webm|wmv|flv|mpg|mpeg)$/i);
  videoPath = cfg.workRoot + '/' + jobId + '_input.' + (m ? m[1].toLowerCase() : 'avi');
} else {
  videoPath = String(input.videoPath || cfg.manualVideoPath);
  if (isWebhook && !videoPath.startsWith(cfg.workRoot + '/')) {
    throw new Error('videoPath doit se trouver sous ' + cfg.workRoot + ' lorsqu\'il est fourni via le Webhook.');
  }
}
if (!/^\/[A-Za-z0-9_\-. \/]+$/.test(videoPath) || videoPath.includes('..')) {
  throw new Error('Chemin vidéo invalide (caractères autorisés : lettres, chiffres, _ - . espace /) : ' + videoPath);
}

return {
  json: {
    jobId, jobDir, framesDir, videoPath, hasUpload,
    binaryKey: hasUpload ? binKeys[0] : null,
    source: isWebhook ? 'webhook' : 'manual',
    startedAt: new Date().toISOString(),
    config: cfg
  },
  binary: item.binary
};

const ctx = $('Init Job').first().json;
const cfg = ctx.config;
const out = $input.first().json;

let info;
try { info = JSON.parse(out.stdout); }
catch (e) { throw new Error('ffprobe : sortie illisible. ' + String(out.stdout || out.stderr || '').slice(0, 300)); }

const v = (info.streams || []).find(s => s.codec_type === 'video');
if (!v) throw new Error('Aucun flux vidéo détecté dans le fichier.');

const rate = (v.avg_frame_rate && v.avg_frame_rate !== '0/0') ? v.avg_frame_rate : (v.r_frame_rate || '0/1');
const parts = String(rate).split('/').map(Number);
const fps = parts[1] ? parts[0] / parts[1] : 0;

let duration = parseFloat((info.format && info.format.duration) || v.duration || 0);
if (!(duration > 0) && v.nb_frames && fps) duration = Number(v.nb_frames) / fps;
if (!(duration > 0)) throw new Error('Durée de la vidéo introuvable (fichier tronqué ?).');

let interval = cfg.frameIntervalSec;
let note = '';
if (cfg.mode === 'interval') {
  const est = Math.ceil(duration / interval);
  if (est > cfg.maxFrames) {
    interval = Math.ceil(duration / cfg.maxFrames);
    note = 'Intervalle porté à ' + interval + ' s pour respecter maxFrames=' + cfg.maxFrames + '.';
  }
}

const scale = "scale='min(" + cfg.frameWidth + ",iw)':-2";
const vf = cfg.mode === 'interval'
  ? 'fps=' + (1 / interval).toFixed(6) + ',' + scale + ',showinfo'
  : "select='eq(n,0)+gt(scene," + cfg.sceneThreshold + ")+gte(t-prev_selected_t," + cfg.maxGapSec + ")'," + scale + ',showinfo';

const log = ctx.jobDir + '/ffmpeg.log';
const cmd = [
  'mkdir -p "' + ctx.framesDir + '"',
  'rm -f "' + ctx.framesDir + '"/f_*.jpg',
  '(ffmpeg -hide_banner -nostats -y -i "' + ctx.videoPath + '" -vf "' + vf + '" -fps_mode vfr -q:v ' + cfg.jpegQuality +
    ' -frames:v ' + cfg.maxFrames + ' "' + ctx.framesDir + '/f_%05d.jpg" 2> "' + log +
    '" || { tail -n 20 "' + log + '" >&2; exit 1; })',
  'grep Parsed_showinfo "' + log + '" | grep -o "pts_time:[0-9.]*" | cut -d: -f2',
  'echo "FILES:$(ls "' + ctx.framesDir + '" | wc -l)"'
].join(' && ');

return [{ json: {
  mode: cfg.mode, intervalUsed: interval, duration, fps,
  width: v.width, height: v.height, codec: v.codec_name,
  vf, note, ffmpegCmd: cmd
} }];

const ctx = $('Init Job').first().json;
const plan = $('Plan Extraction').first().json;
const lines = String($input.first().json.stdout || '').split('\n').map(s => s.trim()).filter(Boolean);

const filesLine = lines.find(l => l.startsWith('FILES:'));
const files = filesLine ? parseInt(filesLine.split(':')[1], 10) : 0;
const ts = lines.filter(l => /^[0-9]+(\.[0-9]+)?$/.test(l)).map(Number);

const n = Math.min(ts.length || files, files, ctx.config.maxFrames);
if (!n) throw new Error('Aucune frame extraite (vidéo vide, ou seuil de scène trop élevé).');

const tc = s => {
  s = Math.max(0, Math.round(s));
  return [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60].map(x => String(x).padStart(2, '0')).join(':');
};

const out = [];
for (let i = 0; i < n; i++) {
  const t = ts[i] !== undefined ? ts[i] : i * plan.intervalUsed;
  out.push({ json: {
    index: i + 1,
    timestampSec: Math.round(t * 10) / 10,
    timecode: tc(t),
    framePath: ctx.framesDir + '/f_' + String(i + 1).padStart(5, '0') + '.jpg'
  } });
}
return out;

const ctx = $('Init Job').first().json;
const cfg = ctx.config;

// Métadonnées de toutes les frames (index -> timecode)
const meta = {};
for (const f of $('Build Frame List').all()) meta[f.json.index] = f.json;

// Frames de ce lot (binaires lus depuis le disque)
const items = $input.all();
const frames = [];
const images = [];
for (let i = 0; i < items.length; i++) {
  const key = Object.keys(items[i].binary || {})[0];
  if (!key) continue;
  const name = items[i].binary[key].fileName || '';
  const m = name.match(/f_(\d+)\.jpe?g$/i);
  const f = m ? meta[parseInt(m[1], 10)] : null;
  if (!f) throw new Error('Frame inattendue : ' + name);
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  frames.push({ index: f.index, timestampSec: f.timestampSec, timecode: f.timecode });
  images.push(buf.toString('base64'));
}
if (!frames.length) throw new Error('Aucune frame dans ce lot.');

// Contexte : dernières analyses du lot précédent (continuité du récit)
let previous = [];
if ($runIndex > 0 && cfg.contextFramesCount > 0) {
  try {
    previous = $('Parse Vision Response').all(0, $runIndex - 1).map(i => i.json).slice(-cfg.contextFramesCount);
  } catch (e) { previous = []; }
}
const ctxText = previous.length
  ? 'Contexte (dernières captures déjà analysées) :\n' +
    previous.map(p => '- [' + p.timecode + '] (' + (p.app || '?') + ') ' + (p.action || p.summary || '')).join('\n')
  : 'Aucun contexte antérieur : ce sont les premières captures de la session.';

const L = cfg.language;
const SYSTEM = [
  "Tu es un analyste spécialisé dans l'audit de sessions de connexion à distance (RDP, VNC, SSH, console d'hyperviseur) enregistrées en vidéo sur une machine virtuelle.",
  "Tu reçois des captures d'écran successives, chacune identifiée par un numéro et un timecode. Pour CHAQUE capture, tu décris factuellement ce qui est visible et ce que l'utilisateur est en train de faire.",
  'Règles :',
  "- Ne décris que ce que tu vois ; n'invente rien. Si un texte est illisible, écris \"[illisible]\".",
  '- Transcris fidèlement les commandes, chemins, noms d\'hôtes, URLs et messages d\'erreur visibles.',
  '- Ne recopie JAMAIS la valeur d\'un mot de passe, token, clé ou secret : signale uniquement son type et son emplacement.',
  '- Compare avec le contexte précédent pour dire si l\'écran a changé de façon significative.',
  '- Rédige tous les champs textuels en ' + L + '.',
  '- Réponds UNIQUEMENT par un objet JSON valide, sans texte autour ni balises markdown.'
].join('\n');

const SCHEMA = 'Réponds avec exactement cet objet JSON (un élément par capture, dans l\'ordre, avec le frame_index fourni) :\n' +
  '{"frames":[{"frame_index":0,"foreground_app":"application ou fenêtre au premier plan","screen_summary":"1 à 2 phrases","action":"action probable de l\'utilisateur","changed":true,"visible_text":["lignes de texte importantes (max 8)"],"commands_or_inputs":["commandes tapées ou saisies"],"paths_hosts_services":["fichiers, chemins, hôtes, URLs, services"],"errors_or_warnings":["messages d\'erreur ou d\'avertissement"],"sensitive_data":[{"type":"password|token|key|personal_data|other","where":"emplacement sans la valeur"}],"confidence":"high|medium|low"}]}';

const sessionLine = cfg.sessionContext ? 'Contexte de la session : ' + cfg.sessionContext + '\n\n' : '';
const listing = 'Captures fournies, dans l\'ordre : ' + frames.map(f => '#' + f.index + ' (' + f.timecode + ')').join(', ') + '.';
const userText = ctxText + '\n\n' + sessionLine + listing + '\n\n' + SCHEMA;

let url, body;
if (cfg.provider === 'anthropic') {
  const content = [];
  for (let i = 0; i < frames.length; i++) {
    content.push({ type: 'text', text: 'Capture #' + frames[i].index + ' - timecode ' + frames[i].timecode });
    content.push({ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: images[i] } });
  }
  content.push({ type: 'text', text: userText });
  url = 'https://api.anthropic.com/v1/messages';
  body = {
    model: cfg.visionModel,
    max_tokens: Math.min(8000, 700 * frames.length + 500),
    system: SYSTEM,
    messages: [{ role: 'user', content }]
  };
} else {
  url = cfg.ollamaUrl + '/api/chat';
  body = {
    model: cfg.ollamaVisionModel,
    stream: false,
    format: 'json',
    options: { temperature: 0, num_ctx: cfg.ollamaVisionNumCtx },
    messages: [
      { role: 'system', content: SYSTEM },
      { role: 'user', content: userText, images }
    ]
  };
}

return [{ json: { provider: cfg.provider, url, body, frames } }];

const expected = $('Build Vision Request').last().json.frames;
const res = $input.first().json;

let text = '';
let err = null;
if (res.error) err = typeof res.error === 'string' ? res.error : JSON.stringify(res.error).slice(0, 300);
else if (Array.isArray(res.content)) text = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
else if (res.message && res.message.content) text = res.message.content;
else err = 'Réponse inattendue du fournisseur LLM';

function extractJson(t) {
  let s = String(t).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(s); } catch (e) { /* on tente de isoler l'objet */ }
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) return JSON.parse(s.slice(a, b + 1));
  throw new Error('JSON introuvable');
}

let list = [];
if (!err) {
  try {
    const parsed = extractJson(text);
    list = Array.isArray(parsed) ? parsed : (parsed.frames || parsed.captures || []);
  } catch (e) { err = 'JSON invalide : ' + String(text).slice(0, 200); }
}

const toArr = v => Array.isArray(v) ? v.map(x => typeof x === 'string' ? x : JSON.stringify(x)).filter(Boolean)
  : (v ? [String(v)] : []);
const sens = v => Array.isArray(v)
  ? v.map(x => typeof x === 'string' ? x : ((x.type || 'other') + (x.where ? ' (' + x.where + ')' : '')))
  : toArr(v);

const byIndex = new Map();
for (const r of list) if (r && r.frame_index !== undefined) byIndex.set(Number(r.frame_index), r);

const out = expected.map((f, pos) => {
  const r = byIndex.get(f.index) || (byIndex.size === 0 ? list[pos] : undefined);
  if (!r) {
    return { json: {
      index: f.index, timestampSec: f.timestampSec, timecode: f.timecode,
      app: '', summary: '(analyse indisponible)', action: '(analyse indisponible)', changed: true,
      visibleText: [], commands: [], targets: [], errors: [], sensitive: [],
      confidence: 'low', parseError: true, errorDetail: err || 'frame absente de la réponse'
    } };
  }
  return { json: {
    index: f.index, timestampSec: f.timestampSec, timecode: f.timecode,
    app: r.foreground_app || '', summary: r.screen_summary || '', action: r.action || '',
    changed: r.changed !== false,
    visibleText: toArr(r.visible_text), commands: toArr(r.commands_or_inputs),
    targets: toArr(r.paths_hosts_services), errors: toArr(r.errors_or_warnings),
    sensitive: sens(r.sensitive_data), confidence: r.confidence || 'medium', parseError: false
  } };
});
return out;

const ctx = $('Init Job').first().json;
const cfg = ctx.config;
const plan = $('Plan Extraction').first().json;
const frames = $input.all().map(i => i.json).sort((a, b) => a.index - b.index);

const tc = s => {
  s = Math.max(0, Math.round(s));
  return [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60].map(x => String(x).padStart(2, '0')).join(':');
};
const clip = (s, n) => (String(s).length > n ? String(s).slice(0, n - 1) + '…' : String(s));

// 1) Fusion des frames consécutives "sans changement"
const entries = [];
for (const f of frames) {
  const prev = entries[entries.length - 1];
  const trivial = f.changed === false && !f.commands.length && !f.errors.length && !f.sensitive.length && !f.parseError;
  if (prev && trivial) { prev.untilSec = f.timestampSec; prev.frameCount += 1; continue; }
  entries.push(Object.assign({}, f, { untilSec: f.timestampSec, frameCount: 1 }));
}

// 2) Rendu texte avec compaction progressive si la chronologie est trop longue
function render(level) {
  const lines = [];
  let lastApp = null;
  for (const e of entries) {
    const important = e.commands.length || e.errors.length || e.sensitive.length || e.app !== lastApp;
    lastApp = e.app;
    if (level >= 2 && !important) continue;
    const range = e.untilSec > e.timestampSec ? '→' + tc(e.untilSec) : '';
    let line = '[' + e.timecode + range + '] (' + (e.app || '?') + ') ' + (e.action || e.summary);
    if (level === 0 && e.summary && e.summary !== e.action) line += ' — ' + clip(e.summary, 200);
    if (e.commands.length) line += ' | CMD: ' + e.commands.map(c => clip(c, 200)).join(' ; ');
    if (level === 0 && e.visibleText.length) line += ' | TEXTE: ' + e.visibleText.slice(0, 3).map(t => clip(t, 120)).join(' / ');
    if (level <= 1 && e.targets.length) line += ' | CIBLES: ' + e.targets.slice(0, 5).map(t => clip(t, 120)).join(' ; ');
    if (e.errors.length) line += ' | ERREUR: ' + e.errors.map(t => clip(t, 160)).join(' ; ');
    if (e.sensitive.length) line += ' | SENSIBLE: ' + e.sensitive.join(' ; ');
    lines.push(line);
  }
  return lines.join('\n');
}
let level = 0;
let timeline = render(0);
while (timeline.length > cfg.summaryMaxChars && level < 2) { level++; timeline = render(level); }
if (timeline.length > cfg.summaryMaxChars) timeline = timeline.slice(0, cfg.summaryMaxChars) + '\n[... chronologie tronquée ...]';

// 3) Statistiques
const apps = {};
for (const f of frames) if (f.app) apps[f.app] = (apps[f.app] || 0) + 1;
const stats = {
  frames: frames.length,
  parseErrors: frames.filter(f => f.parseError).length,
  entries: entries.length,
  compactionLevel: level,
  commandsCount: frames.reduce((n, f) => n + f.commands.length, 0),
  errorsCount: frames.filter(f => f.errors.length).length,
  sensitiveCount: frames.filter(f => f.sensitive.length).length,
  topApps: Object.entries(apps).sort((a, b) => b[1] - a[1]).slice(0, 8).map(x => x[0])
};

// 4) Requête de synthèse
const L = cfg.language;
const SYSTEM = [
  "Tu es un auditeur technique. À partir de la chronologie d'une session de connexion à distance sur une machine virtuelle (extraite image par image d'un enregistrement vidéo), tu rédiges un compte rendu clair, factuel et exploitable.",
  "Règles : ne rien inventer ; signaler explicitement toute incertitude ; ne jamais reproduire de mot de passe, token ou secret ; utiliser les timecodes (hh:mm:ss) pour référencer les événements ; rédiger en " + L + '.'
].join('\n');

const userText =
  'Contexte de la session : ' + (cfg.sessionContext || 'non précisé') + '\n' +
  'Durée de la vidéo : ' + tc(plan.duration) + ' — ' + frames.length + ' captures analysées (' +
  (plan.mode === 'interval' ? '1 toutes les ' + plan.intervalUsed + ' s' : 'détection de changement de scène') + ').\n\n' +
  'Chronologie brute, format [timecode] (application) action | CMD | TEXTE | CIBLES | ERREUR | SENSIBLE. ' +
  'Une flèche (→) indique une période sans changement visible.\n\n<chronologie>\n' + timeline + '\n</chronologie>\n\n' +
  'Rédige le compte rendu en Markdown, en ' + L + ', avec exactement ces sections (## niveau 2) :\n' +
  '1. Résumé exécutif (5 à 8 lignes : objectif probable de la session, déroulé global, résultat)\n' +
  '2. Contexte technique (OS, outils, applications, hôtes et comptes visibles)\n' +
  '3. Déroulé par phases (phases chronologiques avec plages de timecodes et ce qui a été fait)\n' +
  '4. Commandes et actions notables (tableau : timecode | commande ou action | effet)\n' +
  '5. Fichiers, services, hôtes et configurations touchés\n' +
  '6. Erreurs, échecs et anomalies (avec timecodes)\n' +
  '7. Données sensibles exposées à l\'écran (type et timecode uniquement, jamais la valeur)\n' +
  '8. Limites de l\'analyse (ce qui ne peut pas être déterminé : actions entre deux captures, texte illisible, etc.)';

let url, body;
if (cfg.provider === 'anthropic') {
  url = 'https://api.anthropic.com/v1/messages';
  body = { model: cfg.summaryModel, max_tokens: 8000, system: SYSTEM, messages: [{ role: 'user', content: userText }] };
} else {
  url = cfg.ollamaUrl + '/api/chat';
  body = {
    model: cfg.ollamaSummaryModel, stream: false,
    options: { temperature: 0.2, num_ctx: cfg.ollamaSummaryNumCtx },
    messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: userText }]
  };
}

return [{ json: { provider: cfg.provider, url, body, entries, stats, timelineChars: timeline.length } }];

const res = $input.first().json;
let md = '';
let warning = null;

if (res.error) warning = typeof res.error === 'string' ? res.error : JSON.stringify(res.error).slice(0, 300);
else if (Array.isArray(res.content)) md = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
else if (res.message && res.message.content) md = res.message.content;

if (!String(md).trim()) {
  warning = warning || 'réponse vide';
  md = '> ⚠️ La synthèse automatique a échoué (' + warning + '). Se référer à la chronologie détaillée en annexe.';
}
return [{ json: { summaryMarkdown: String(md).trim(), warning } }];

const ctx = $('Init Job').first().json;
const cfg = ctx.config;
const plan = $('Plan Extraction').first().json;
const tl = $('Build Timeline').first().json;
const sum = $input.first().json;
const stats = tl.stats;

const tc = s => {
  s = Math.max(0, Math.round(s));
  return [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60].map(x => String(x).padStart(2, '0')).join(':');
};
const esc = s => String(s || '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');

const models = cfg.provider === 'anthropic'
  ? 'Anthropic — vision : ' + cfg.visionModel + ', synthèse : ' + cfg.summaryModel
  : 'Ollama (local) — vision : ' + cfg.ollamaVisionModel + ', synthèse : ' + cfg.ollamaSummaryModel;
const sampling = plan.mode === 'interval'
  ? '1 capture toutes les ' + plan.intervalUsed + ' s'
  : 'détection de changement de scène (seuil ' + cfg.sceneThreshold + ', max ' + cfg.maxGapSec + ' s entre deux captures)';

const header = [
  '# Compte rendu de session distante', '',
  '| | |', '|---|---|',
  '| Job | ' + ctx.jobId + ' |',
  '| Vidéo | ' + ctx.videoPath + ' |',
  '| Durée | ' + tc(plan.duration) + ' |',
  '| Résolution source | ' + plan.width + '×' + plan.height + ' (' + plan.codec + ') |',
  '| Échantillonnage | ' + sampling + ' |',
  '| Captures analysées | ' + stats.frames + ' (échecs d\'analyse : ' + stats.parseErrors + ') |',
  '| Modèles | ' + models + ' |',
  '| Généré le | ' + new Date().toISOString() + ' |'
].join('\n');

const rows = tl.entries.map(e => {
  const range = e.untilSec > e.timestampSec ? ' → ' + tc(e.untilSec) : '';
  const cmds = e.commands.length ? ' — `' + esc(e.commands.join(' ; ')) + '`' : '';
  return '| ' + e.timecode + range + ' | ' + esc(e.app) + ' | ' + esc(e.action || e.summary) + cmds + ' |';
});
const annexA = ['## Annexe A — Chronologie détaillée', '', '| Timecode | Application | Action |', '|---|---|---|'].concat(rows).join('\n');

const alerts = [];
for (const e of tl.entries) {
  for (const x of e.errors) alerts.push('- [' + e.timecode + '] ❌ ' + esc(x));
  for (const x of e.sensitive) alerts.push('- [' + e.timecode + '] 🔐 ' + esc(x));
}
const annexB = '## Annexe B — Alertes (erreurs et données sensibles)\n\n' + (alerts.length ? alerts.join('\n') : '_Aucune détectée._');

const reportMarkdown = [header, sum.summaryMarkdown, annexA, annexB].join('\n\n---\n\n');

const timeline = tl.entries.map(e => ({
  timecode: e.timecode, untilTimecode: tc(e.untilSec), app: e.app, summary: e.summary, action: e.action,
  commands: e.commands, targets: e.targets, errors: e.errors, sensitive: e.sensitive,
  confidence: e.confidence, frames: e.frameCount, parseError: e.parseError
}));

return [{ json: {
  reportMarkdown, timeline,
  response: {
    status: 'done',
    jobId: ctx.jobId,
    videoDuration: tc(plan.duration),
    framesAnalysed: stats.frames,
    analysisFailures: stats.parseErrors,
    summaryWarning: sum.warning,
    files: { report: ctx.jobDir + '/report.md', timeline: ctx.jobDir + '/timeline.json' },
    report: reportMarkdown
  }
} }];

const ctx = $('Init Job').first().json;
const fin = $input.first().json;

const mk = async (name, content, mime, target) => ({
  json: { targetPath: target },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from(content, 'utf8'), name, mime) }
});

return [
  await mk('report.md', fin.reportMarkdown, 'text/markdown', ctx.jobDir + '/report.md'),
  await mk('timeline.json', JSON.stringify(fin.timeline, null, 2), 'application/json', ctx.jobDir + '/timeline.json')
];
